import{_ as t,o as i,c as s,a2 as a}from"./chunks/framework.CRkTBNIT.js";const m=JSON.parse('{"title":"14.17 Classic System Design Problems Applied","description":"","frontmatter":{},"headers":[],"relativePath":"system-design/14.17-classic-system-design.md","filePath":"system-design/14.17-classic-system-design.md"}'),o={name:"system-design/14.17-classic-system-design.md"};function r(n,e,l,c,d,u){return i(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="_14-17-classic-system-design-problems-applied" tabindex="-1">14.17 Classic System Design Problems Applied <a class="header-anchor" href="#_14-17-classic-system-design-problems-applied" aria-label="Permalink to &quot;14.17 Classic System Design Problems Applied&quot;">​</a></h1><p>This chapter demonstrates how the foundational architectural building blocks of OmniPost (priority queues, idempotency, rate limiters, fallback routing) can be adapted to solve classic system design interview problems.</p><hr><h2 id="_1-design-a-notification-system-at-100x-scale" tabindex="-1">1. Design a Notification System at 100x Scale <a class="header-anchor" href="#_1-design-a-notification-system-at-100x-scale" aria-label="Permalink to &quot;1. Design a Notification System at 100x Scale&quot;">​</a></h2><ul><li><strong>Requirements</strong>: Deliver 1 billion notifications daily across 50 countries.</li><li><strong>Design</strong>: Deploy edge API gateways in 3 global regions (US, EU, APAC); buffer ingestion into regional Kafka clusters; use local worker fleets with Redis token bucket rate limiters; enforce local quiet hours via <code>zoneinfo</code>.</li></ul><hr><h2 id="_2-design-a-distributed-rate-limiter" tabindex="-1">2. Design a Distributed Rate Limiter <a class="header-anchor" href="#_2-design-a-distributed-rate-limiter" aria-label="Permalink to &quot;2. Design a Distributed Rate Limiter&quot;">​</a></h2><ul><li><strong>Requirements</strong>: Limit user API requests to 1,000 per hour across a distributed cluster.</li><li><strong>OmniPost Building Block</strong>: Reuse the token bucket algorithm from <code>queues/dispatcher.py</code>, replacing the in-process dictionary with a Redis cluster executing atomic Lua scripts.</li></ul><hr><h2 id="_3-design-a-high-throughput-job-scheduler" tabindex="-1">3. Design a High-Throughput Job Scheduler <a class="header-anchor" href="#_3-design-a-high-throughput-job-scheduler" aria-label="Permalink to &quot;3. Design a High-Throughput Job Scheduler&quot;">​</a></h2><ul><li><strong>Requirements</strong>: Schedule millions of delayed tasks with sub-second execution accuracy.</li><li><strong>OmniPost Building Block</strong>: Adapt <code>ScheduledQueueManager</code> from <code>queues/dispatcher.py</code>, backing future timestamps with Redis Sorted Sets where score is the epoch execution time.</li></ul><hr><h2 id="_4-say-it-out-loud" tabindex="-1">4. Say It Out Loud <a class="header-anchor" href="#_4-say-it-out-loud" aria-label="Permalink to &quot;4. Say It Out Loud&quot;">​</a></h2><blockquote><p>&quot;The architectural patterns we built in OmniPost directly transfer to classic system design challenges. For example, to design a distributed rate limiter, we can take our token bucket implementation from <code>queues/dispatcher.py</code> and run it against Redis with Lua scripts to achieve atomic, cross-node token consumption with sub-millisecond latency.&quot;</p></blockquote>',14)])])}const g=t(o,[["render",r]]);export{m as __pageData,g as default};
